const root = path.resolve(__dirname, '..');
const out = path.join(root, 'output/worksheet-design-20261012');
const runtimePackages = process.env.WORKSHEET_NODE_MODULES || path.join(require('node:os').homedir(), '.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules');
const runtimeRequire = createRequire(path.join(runtimePackages, '../package.json'));
const { chromium } = runtimeRequire('playwright');
const artFiles = { a: 'storybook', b: 'play', c: 'journal' };
const art = (theme, motif, size = 120) => {
  const cells = { rabbit: [0, 0], carrot: [1, 0], apple: [0, 1], bag: [1, 1], cat: [0, 1.93], hat: [1, 2] };
  const [x, y] = cells[motif];
  return `<span class="art" style="width:${size}px;height:${size}px"><img alt="${motif}" src="assets/${artFiles[theme]}.png" style="left:${-x * 100}%;top:${-y * 100}%"></span>`;
};
const cells = (letters, cls = '') => `<div class="cells ${cls}">${letters.map((v, i) => `<div class="cell ${cls === 'word-cells' ? i < 2 ? 'model' : i < 4 ? 'trace' : '' : i === 0 ? 'model' : i < 3 ? 'trace' : ''}">${v}</div>`).join('')}</div>`;
const section = (n, title, note = '') => `<div class="section-title"><span class="step">${n}</span><h2>${title}</h2>${note ? `<span class="note">${note}</span>` : ''}</div>`;
const wordline = (word, empty = false) => `<div class="wordline"><span class="${empty ? '' : 'trace'}">${empty ? '' : word}</span></div>`;
const header = (theme, lang, index) => `<header><img class="logo" src="assets/logo.webp" alt="탱고북"><span class="series">${theme === 'a' ? '작은 이야기, 큰 배움' : theme === 'b' ? '오리고 붙이는 글자 놀이터' : '나의 첫 배움 노트'}</span><span class="language">${lang === 'ko' ? '한글' : 'ENGLISH'} · ${index}</span></header>`;
const name = () => '<div class="name">이름 <span></span> 날짜 <span></span></div>';
const footer = (theme, lang, index) => `<footer><span>TangoBook · ${theme === 'a' ? 'STORY & LETTERS' : theme === 'b' ? 'PLAY & LETTERS' : 'LITTLE LEARNING JOURNAL'}</span><span class="check">오늘도 한 장 완성했어요 <i></i></span><b>${String(index).padStart(2, '0')}</b></footer>`;
function page(theme, lang, index, body) {
  return `<article class="page ${theme} ${lang}" id="sheet-${index}" data-theme="${theme}" data-lang="${lang}">${header(theme, lang, index)}${body}${footer(theme, lang, index)}</article>`;
}
